from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size *= 2

        seg = [-1] * (2 * size)

        for i, cap in enumerate(baskets):
            seg[size + i] = cap

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        unplaced = 0

        for fruit in fruits:
            if seg[1] < fruit:
                unplaced += 1
                continue

            idx = 1
            while idx < size:
                if seg[2 * idx] >= fruit:
                    idx = 2 * idx
                else:
                    idx = 2 * idx + 1

            seg[idx] = -1
            idx //= 2
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        return unplaced
